`timescale 1ns/1ps
// Self-checking unit testbench for DDR1_DLL_TDC (structural-signed flash
// TDC, IMPL=0 behavioral cells so the chain has realistic timing).
//
// Method: CKIN is a free-running 100 MHz clock.  MASTER is generated by a
// controllable delayed copy of CKIN (transport delay, retriggerable
// per-phase).  For each injected residual e (positive = master LATE), the
// TDC measurement is read after the pipeline settles and compared:
//   * in-range residuals: |E_MEAS - e| <= 1.5 taps
//   * sign correctness across zero
//   * deep offsets: correct-sign clamp, no modulo aliasing
//   * MEAS_VLD raises
//
// Run:
//   iverilog -g2012 -o /tmp/opencode/ddr1_dll_tdc_unit.vvp \
//     src/ddr1_dll_tdc_tb.v src/ddr1_dll_tdc.v && vvp ...
// exits nonzero on any failure.

module ddr1_dll_tdc_tb;
    localparam integer TCK_NS = 10;
    localparam integer TAU    = 65;     // behavioral tap step (TT)

    reg ckin = 1'b0;
    reg rst  = 1'b1;
    always #(TCK_NS/2.0) ckin = ~ckin;

    // retriggerable delayed copy of CKIN: master = ckin + offset_ps
    reg signed [31:0] offset_ps = 0;
    reg master_dly = 1'b0;
    always @(ckin) begin
        if (offset_ps >= 0)
            master_dly <= #(offset_ps/1000.0) ckin;
        else
            master_dly <= #((TCK_NS*1000+offset_ps)/1000.0) ckin;
    end

    wire signed [15:0] e_meas;
    wire meas_vld;

    DDR1_DLL_TDC #(
        .NTAP(32), .TDC_STEP_PS(TAU), .IMPL(0)
    ) dut (
        .CKIN(ckin), .MASTER(master_dly), .RST(rst),
        .E_MEAS(e_meas), .MEAS_VLD(meas_vld));

    integer errors = 0;
    integer checks = 0;
    integer fd;

    task chk(input cond, input [8*72-1:0] name);
        begin
            checks = checks + 1;
            if (cond) begin
                $display("PASS: %0s", name);
                $fdisplay(fd, "PASS: %0s", name);
            end else begin
                errors = errors + 1;
                $display("FAIL: %0s", name);
                $fdisplay(fd, "FAIL: %0s", name);
            end
        end
    endtask

    // set a residual, let the chain+capture pipeline settle, read
    task measure(input integer offs, output integer em);
        begin
            offset_ps = offs;
            #(8*TCK_NS);          // pipeline flush + several captures
            em = e_meas;
        end
    endtask

    integer em;

    initial begin
        fd = $fopen("sim/outputs/ddr1/ddr1_dll_tdc_unit_tb.log", "w");
        $display("=== DDR1_DLL_TDC unit TB start ===");
        rst = 1'b1; #(3*TCK_NS);
        rst = 1'b0; #(5*TCK_NS);

        chk(meas_vld === 1'b1, "check0: MEAS_VLD raises");

        // ---- zero residual ----
        measure(0, em);
        $display("e=0 -> %0d", em);
        chk(em >= -TAU && em <= TAU, "check1: zero residual reads within +-1 tap");

        // ---- small signed residuals (in lock-band scale) ----
        measure(192, em);
        $display("e=+192 -> %0d", em);
        chk(em > 0 && em <= 192+2*TAU && em >= 192-2*TAU,
            "check2a: +192ps reads positive within +-2 taps");
        measure(-192, em);
        $display("e=-192 -> %0d", em);
        chk(em < 0 && em >= -192-2*TAU && em <= -192+2*TAU,
            "check2b: -192ps reads negative within +-2 taps");

        // ---- loss-band scale ----
        measure(640, em);
        $display("e=+640 -> %0d", em);
        chk(em >= 640-2*TAU && em <= 640+2*TAU,
            "check3a: +640ps within +-2 taps");
        measure(-640, em);
        $display("e=-640 -> %0d", em);
        chk(em <= -640+2*TAU && em >= -640-2*TAU,
            "check3b: -640ps within +-2 taps");

        // ---- quantization: 1-tap granularity ----
        measure(TAU, em);
        chk((em % TAU == 0) || (em % TAU == -0),
            "check4: measurement is tap-quantized");

        // ---- deep positive: clamps positive, NO aliasing to negative ----
        measure(2500, em);
        $display("e=+2500 -> %0d", em);
        chk(em > 0, "check5a: +2500ps (beyond chain) clamps POSITIVE, no modulo alias");
        // +6000 was REMOVED as a positive-clamp check: physically it is
        // beyond the unambiguous window.  Valid positive saturation holds
        // for e in [+(NTAP-NOFF)*tau, +(T/2 - D0)] = [+1040, +2920]ps; past
        // the falling-wavefront interference zone (and in any case past
        // +-T/2) every periodic measurement aliases, this one included.
        // The acquisition-residual budget (docs/DDR1_TDC_DESIGN.md) must
        // keep initial residuals inside the unambiguous window.
        measure(2000, em);
        $display("e=+2000 -> %0d", em);
        chk(em > 0, "check5b: +2000ps (inside saturation window) clamps POSITIVE");

        // ---- deep negative: clamps negative ----
        measure(-2500, em);
        $display("e=-2500 -> %0d", em);
        chk(em < 0, "check5c: -2500ps clamps NEGATIVE");

        // ---- return to zero ----
        measure(0, em);
        chk(em >= -TAU && em <= TAU, "check6: returns to zero after excursions");

        $fdisplay(fd, "SUMMARY: %0d checks, %0d errors", checks, errors);
        $display("=== TB done, %0d checks, errors=%0d ===", checks, errors);
        $fclose(fd);
        if (errors != 0) $fatal(1, "ddr1_dll_tdc_tb FAILED");
        $finish;
    end

    initial begin
        #(2_000_000);
        $display("FAIL: global timeout");
        $fatal(1, "watchdog");
    end
endmodule
